import subprocess
from pathlib import Path

from .term import die


def parse_flags(args: list[str], spec: dict[str, str]) -> dict[str, object]:
    """spec: {'--flag': 'str'|'bool'}; returns dict keyed by flag name sans --.
10→
    Any argument outside ``spec`` fails; ``-h``/``--help`` sets ``out['help']``."""
    out: dict[str, object] = {
        k.lstrip("-").replace("-", "_"): ("" if t == "str" else False)
        for k, t in spec.items()
    }
    i = 0
    while i < len(args):
        a = args[i]
        if a in ("-h", "--help"):
20→            out["help"] = True
            i += 1
            continue
        if a not in spec:
            die(f"unknown flag: {a}")
        key = a.lstrip("-").replace("-", "_")
        if spec[a] == "bool":
            out[key] = True
            i += 1
        else:
30→            if i + 1 >= len(args):
                die(f"flag {a} requires value")
            out[key] = args[i + 1]
            i += 2
    out.setdefault("help", False)
    return out


def parse_args(args: list[str], spec: dict[str, str],
               max_pos: int = 0) -> tuple[dict[str, object], list[str]]:
40→    """Parse flags and positional arguments, returning ``(options, positionals)``.

    Unknown flags, missing values, and excess positionals fail.
    """
    opts: dict[str, object] = {
        k.lstrip("-").replace("-", "_"): ("" if t == "str" else False)
        for k, t in spec.items()
    }
    opts.setdefault("help", False)
    pos: list[str] = []
50→    i = 0
    while i < len(args):
        a = args[i]
        if a in ("-h", "--help"):
            opts["help"] = True
            i += 1
            continue
        if a.startswith("-") and a != "-":
            if a not in spec:
                die(f"unknown flag: {a}")
60→            key = a.lstrip("-").replace("-", "_")
            if spec[a] == "bool":
                opts[key] = True
                i += 1
            else:
